INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷261·陈思让传·召还与磁州驻防", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/songshi-261-chen-recall-cizhou/source.txt", "note": "《宋史》卷261·陈思让传·召还与磁州驻防，段落 songshi-9c6e46fee832-p058036；已核上下文及传主，纸本及异文待核。", "id": "a79fe785-777d-526e-81b7-9a638eeef8ee"}, {"title": "宋史·卷261·陈思让传·湖南赴援与郢州停军", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/songshi-261-chen-yingzhou/source.txt", "note": "《宋史》卷261·陈思让传·湖南赴援与郢州停军，段落 songshi-9c6e46fee832-p058035；已核上下文及传主，纸本及异文待核。", "id": "540d4746-4f57-5294-92f2-ea738eed7da8"}, {"title": "资治通鉴·卷290·广顺元年·二三月外交与楚国册封", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/tongjian-290-951-february-diplomacy/source.txt", "note": "《资治通鉴》卷290·广顺元年·二三月外交与楚国册封，段落 zizhi-tongjian-a63549944a71-p003444；已核上下文及传主，纸本及异文待核。", "id": "4c7666bc-bea9-50da-a518-408a20aabf85"}, {"title": "新五代史·卷66·楚世家·南唐册封马希萼", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/xinwudaishi-066-chu-investiture/source.txt", "note": "《新五代史》卷66·楚世家·南唐册封马希萼，段落 xin-wudaishi-b08f244b9241-p003332；已核上下文及传主，纸本及异文待核。", "id": "b5e62597-b257-5d89-895e-8dba38722875"}, {"title": "旧五代史·卷111·太祖本纪·澶州任官与晋州战报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-111-jinzhou/source.txt", "note": "《旧五代史》卷111·太祖本纪·澶州任官与晋州战报，段落 jiu-wudaishi-205deb4a7860-p002656；已核上下文及传主，纸本及异文待核。", "id": "4892b94c-c27b-5fc4-9a3c-0588e2b5636e"}, {"title": "旧五代史·卷111·太祖本纪·隰州战报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-111-xizhou/source.txt", "note": "《旧五代史》卷111·太祖本纪·隰州战报，段落 jiu-wudaishi-205deb4a7860-p002657；已核上下文及传主，纸本及异文待核。", "id": "7504ba0b-0629-52bd-bf86-9594aecd71f2"}, {"title": "新五代史·卷11·周本纪·广顺元年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7f523fc68334366ce90d3a6e1465b179c9c38000/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/xinwudaishi-011-first-year-951/source.txt", "note": "《新五代史》卷11·周本纪·广顺元年，段落 xin-wudaishi-b08f244b9241-p000368；已核上下文及传主，纸本及异文待核。", "id": "d3b793df-2c14-5468-91e6-30671d01ef09"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "刘光辅", "aliases": ["劉光輔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的掌书记。951年二月奉命向南唐进贡。生卒年未载。", "biography": null, "status": "draft", "id": "f149dc3c-32e5-5f02-bd24-315df551ceee"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "袅骨支", "aliases": ["䮍骨支"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹使臣。951年二月与后周使者朱宪一同来后周，祝贺郭威即位。《新五代史》字形写作䮍骨支；《旧五代史》同日贺即位使者写郭济，是否同人待核。生卒年未载。", "biography": null, "status": "draft", "id": "ad8456ab-beb9-5d3c-91fc-2a43e270e149"}, {"name": "朱宪（后周使者）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左千牛卫将军。951年受郭威派遣出使契丹，说明改朝原因，并赠金器玉带。与938年后晋内职官朱宪暂无连续履历证据，暂不合并，生卒年未载。", "biography": null, "status": "draft", "id": "d51ae347-5862-5f97-a3e0-11cce3591ce1"}, {"name": "陈思让", "aliases": ["陳思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋作坊使，幽州人。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋军监军。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "59feec41-432b-5d18-829a-46def9523238"}, {"name": "田敏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周尚书左丞。951年二月奉命出使契丹。《旧五代史》也记录他充契丹国信使。生卒年尚未录入。", "biography": null, "status": "draft", "id": "73deef56-8053-59f4-8081-4746e12611ce"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "李巩言", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉通事舍人。951年奉刘崇派遣出使契丹，请求援兵。生卒年未载。", "biography": null, "status": "draft", "id": "f2ad0b09-607f-5d5a-9e94-6773cfb0518b"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "鱼崇远", "aliases": ["魚崇遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：鱼崇远，前襄州支使、山阳人、任记室者。", "biography": null, "status": "draft", "id": "5a54fd61-9a4c-5d53-909b-b052b211a312"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "姚凤", "aliases": ["姚鳳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年李璟任他为建州行营都监，与何敬洙、祖全恩率军增援查文徽。生卒年本段未载。", "biography": null, "status": "draft", "id": "74f180a4-a1e3-5952-a5d4-9d936d1a19ac"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
